package com.example.starter.feed.dto;

import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;

/**
 * 配方中的单项组分（原料或药物添加剂）及其质量占比。
 *
 * @param code  组分编码
 * @param ratio 添加比例（质量占比，0~1）；药物项不得超过字典最大添加比例，恰等于上限合法
 */
public record RatioItem(
        @NotBlank(message = "组分编码不能为空")
        String code,

        @NotNull(message = "添加比例不能为空")
        @DecimalMin(value = "0.000001", message = "添加比例必须为正数")
        @DecimalMax(value = "1.000000", message = "添加比例不得超过 1")
        BigDecimal ratio
) {
}

package com.example.starter.feed.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 配方提交请求。requestId 为幂等键；指纹覆盖 requestId 与下列全部业务字段。
 *
 * @param requestId     幂等键
 * @param formulaCode   配方业务编码；同一编码可提交多个独立版本
 * @param name          配方名称
 * @param targetSpecies 目标动物种类；含药配方必填且须与各药物允许种类匹配
 * @param ingredients   普通原料清单
 * @param drugs         药物添加剂清单；为空表示无药配方
 */
public record FormulaSubmitRequest(
        @NotBlank(message = "requestId 不能为空")
        @Size(max = 64)
        String requestId,

        @NotBlank(message = "配方编码不能为空")
        @Size(max = 64)
        String formulaCode,

        @NotBlank(message = "配方名称不能为空")
        @Size(max = 128)
        String name,

        @Size(max = 64)
        String targetSpecies,

        @Valid
        @Size(max = 100)
        List<RatioItem> ingredients,

        @Valid
        @Size(max = 50)
        List<RatioItem> drugs
) {
}

package com.example.starter.feed.dto;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;

/**
 * 配方提交/重放响应。
 *
 * @param formulaCode   配方编码
 * @param version       新版本号（从 1 递增）
 * @param status        SUBMITTED / REJECTED
 * @param targetSpecies 目标动物种类
 * @param ingredients   原料清单
 * @param drugs         药物清单
 * @param rejectReason  合规拒绝原因；通过为 null
 * @param replayed      是否为同键同参的幂等重放（返回首次结果）
 * @param createdAtUtc  首次提交时刻（UTC）
 */
public record FormulaSubmitResponse(
        String formulaCode,
        int version,
        String status,
        String targetSpecies,
        List<RatioItem> ingredients,
        List<DrugView> drugs,
        String rejectReason,
        boolean replayed,
        Instant createdAtUtc
) {
    /**
     * 药物项视图：携带字典上限与休药天数供调用方复算。
     */
    public record DrugView(String code, BigDecimal ratio, BigDecimal maxRatio, Integer withdrawalDays) {
    }
}

package com.example.starter.feed.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;

