package com.example.starter.feed.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PastOrPresent;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;

import java.time.Instant;

/**
 * 配方投产请求：将已批准（冻结）版本投产到目标养殖批次，并记录末次含药饲喂时刻。
 *
 * <p>含药配方投产要求批次动物种类与配方目标种类一致；投产即生成批准版本的药物快照，
 * 后续配方新版本修改不追溯减轻已产生的休药期义务。</p>
 *
 * @param formulaCode 已批准配方编码
 * @param version     已批准版本号
 * @param batchNo     养殖批次号
 * @param feedAtUtc   末次饲喂该含药饲料的时刻（UTC）；休药期＝该时刻（UTC 日界）＋药物休药天数
 */
public record ProductionRequest(
        @NotBlank(message = "配方编码不能为空")
        @Size(max = 64)
        String formulaCode,

        @Positive(message = "版本号必须为正数")
        int version,

        @NotBlank(message = "批次号不能为空")
        @Size(max = 64)
        String batchNo,

        @NotNull(message = "末次含药饲喂时刻不能为空")
        @PastOrPresent(message = "末次含药饲喂时刻不能晚于当前时刻")
        Instant feedAtUtc
) {
}

package com.example.starter.feed.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.time.Instant;

/**
 * 出栏申请。以 requestId 幂等：同键同参返回首次结果，同键异参返回 409 且不改变状态。
 *
 * <p>休药期届满日（UTC 日历日）当日 24:00（即次日 00:00 UTC）之后方可出栏；
 * 休药期内申请一律拒绝并提示最早合法出栏时刻。出栏为终态，重复申请返回幂等成功。</p>
 *
 * @param requestId      幂等键
 * @param batchNo        养殖批次号
 * @param applyAtUtc     申请出栏时刻（UTC）
 */
public record SlaughterRequest(
        @NotBlank(message = "requestId 不能为空")
        @Size(max = 64)
        String requestId,

        @NotBlank(message = "批次号不能为空")
        @Size(max = 64)
        String batchNo,

        @NotNull(message = "出栏申请时刻不能为空")
        Instant applyAtUtc
) {
}

package com.example.starter.feed.dto;

import java.time.Instant;
import java.time.LocalDate;

/**
 * 出栏申请响应。
 *
 * @param batchNo              批次号
 * @param approved             是否准许出栏
 * @param replayed             是否为同键同参的幂等重放
 * @param status               申请后批次状态：FEEDING / SLAUGHTERED
 * @param earliestSlaughterUtc 最早合法出栏时刻（UTC）；无休药义务时为 null
 * @param rejectReason         拒绝原因（休药期内/动物种类不符等）；准许时为 null
 * @param slaughteredAtUtc     实际出栏时刻（UTC）；未出栏为 null
 * @param appliedAtUtc         本次申请时刻（UTC）
 */
public record SlaughterResponse(
        String batchNo,
        boolean approved,
        boolean replayed,
        String status,
        Instant earliestSlaughterUtc,
        String rejectReason,
        Instant slaughteredAtUtc,
        Instant appliedAtUtc
) {
}

package com.example.starter.feed.dto;

import java.time.Instant;
import java.time.LocalDate;

/**
 * 养殖批次休药期跟踪视图，所有字段均可由投产/饲喂/出栏事件复算。
 *
 * @param batchNo                  批次号
 * @param species                  动物种类
 * @param status                   FEEDING / SLAUGHTERED
 * @param lastMedicatedFeedAtUtc   最晚一次含药饲喂时刻（UTC）；无则 null
 * @param withdrawalUntilDate      休药期届满日（UTC 日历日）；该日 24:00 后可出栏
 * @param earliestSlaughterUtc     最早合法出栏时刻（UTC，届满日次日 00:00）；无休药义务为 null
 * @param governingWithdrawalDays  合并口径下决定性最大休药天数
 * @param slaughteredAtUtc         实际出栏时刻（UTC）；未出栏为 null
 */
public record BatchStatusResponse(
        String batchNo,
        String species,
        String status,
        Instant lastMedicatedFeedAtUtc,
        LocalDate withdrawalUntilDate,
        Instant earliestSlaughterUtc,
        Integer governingWithdrawalDays,
        Instant slaughteredAtUtc
) {
}

