            } catch (DuplicateKeyException e) {
                // 并发提交同一配方编码：重新取最大版本号后重试。
                if (++attempt > 10) {
                    throw ApiException.conflict("配方版本分配冲突，重试次数耗尽");
                }
                version = formulaRepository.maxVersion(request.formulaCode()).orElse(0) + 1;
