package com.example.starter.feed.repo;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.Instant;
import java.time.LocalDate;
import java.util.List;
import java.util.Optional;

/**
 * 养殖批次仓储。批次合并口径休药期字段由服务层在事务内重算后写入。
 */
@Repository
public class BatchRepository {

    private final JdbcTemplate jdbc;

    public BatchRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** herd_batch 表行。 */
    public record BatchRow(
            long id,
            String batchNo,
            String species,
            String status,
            Instant lastMedicatedFeedAtUtc,
            LocalDate withdrawalUntilDate,
            Integer governingWithdrawalDays,
            Instant slaughteredAtUtc,
            Instant createdAtUtc
    ) {
    }

    private static final RowMapper<BatchRow> MAPPER = (rs, n) -> new BatchRow(
            rs.getLong("id"),
            rs.getString("batch_no"),
            rs.getString("species"),
            rs.getString("status"),
            DictRepository.toInstant(rs.getTimestamp("last_medicated_feed_at_utc")),
            rs.getObject("withdrawal_until_date", LocalDate.class),
            (Integer) rs.getObject("governing_withdrawal_days"),
            DictRepository.toInstant(rs.getTimestamp("slaughtered_at_utc")),
            DictRepository.toInstant(rs.getTimestamp("created_at_utc"))
    );

    public void insert(String batchNo, String species) {
        jdbc.update("INSERT INTO herd_batch (batch_no, species, status) VALUES (?,?,'FEEDING')",
                batchNo, species);
    }

    public boolean exists(String batchNo) {
        Long count = jdbc.queryForObject("SELECT COUNT(*) FROM herd_batch WHERE batch_no = ?",
                Long.class, batchNo);
        return count != null && count > 0;
    }

    public Optional<BatchRow> find(String batchNo) {
        return jdbc.query("SELECT * FROM herd_batch WHERE batch_no = ?", MAPPER, batchNo)
                .stream().findFirst();
    }

    public BatchRow get(String batchNo) {
        return find(batchNo).orElseThrow(() ->
                com.example.starter.feed.web.ApiException.notFound("养殖批次不存在: " + batchNo));
    }

    /**
     * 事务内行锁：并发投产/出栏/迟到饲喂以同一行锁串行化，保证合并口径唯一。
     */
    public BatchRow lockAndGet(String batchNo) {
        List<BatchRow> rows = jdbc.query(
                "SELECT * FROM herd_batch WHERE batch_no = ? FOR UPDATE", MAPPER, batchNo);
        return rows.stream().findFirst().orElseThrow(() ->
                com.example.starter.feed.web.ApiException.notFound("养殖批次不存在: " + batchNo));
    }

    /**
     * 重算后写回合并口径休药期字段。
     */
    public void updateWithdrawal(long batchId, Instant lastFeedAtUtc, LocalDate untilDate, Integer maxDays) {
        jdbc.update("UPDATE herd_batch SET last_medicated_feed_at_utc = ?, withdrawal_until_date = ?, "
                        + "governing_withdrawal_days = ? WHERE id = ?",
                lastFeedAt == null ? null : Timestamp.from(lastFeedAtUtc),
                untilDate, maxDays, batchId);
    }

    /**
     * 条件置为出栏终态；仅当当前仍为 FEEDING 时生效，返回受影响行数。
     */
    public int markSlaughteredIfFeeding(long batchId, Instant slaughteredAtUtc) {
        return jdbc.update(
                "UPDATE herd_batch SET status = 'SLAUGHTERED', slaughtered_at_utc = ? "
                        + "WHERE id = ? AND status = 'FEEDING'",
                Timestamp.from(slaughteredAtUtc), batchId);
    }
}

package com.example.starter.feed.service;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.Map;

/**
 * 休药期纯计算工具（UTC 日界口径），无状态、可对任意输入复算。
 *
 * <p>口径（唯一）：</p>
 * <ul>
 *   <li>末次饲喂含药饲料时刻 {@code t}（UTC）所在 UTC 日历日 D；</li>
 *   <li>休药期届满日 = D + N 天（N = 各药物最大休药天数）；</li>
 *   <li>恰满休药天数当日 24:00（即届满日次日 00:00 UTC）之后方可出栏；</li>
 *   <li>判断出栏申请时刻 {@code a} 是否合法：{@code a >= earliestSlaughter}。</li>
 * </ul>
 */
public final class WithdrawalCalculator {

    private WithdrawalCalculator() {
    }

    /**
     * 取某时刻的 UTC 日历日。
     */
    public static LocalDate utcDate(Instant instant) {
        return instant.atZone(ZoneOffset.UTC).toLocalDate();
    }

    /**
     * 计算休药期届满日（UTC）：末次饲喂日 + 休药天数。
     */
    public static LocalDate withdrawalUntilDate(Instant lastFeedAtUtc, int withdrawalDays) {
        if (withdrawalDays < 0) {
            throw new IllegalArgumentException("休药天数不能为负数");
        }
        return utcDate(lastFeedAtUtc).plusDays(withdrawalDays);
    }

    /**
     * 最早合法出栏时刻：届满日次日 00:00 UTC（即届满日当日 24:00）。
     */
    public static Instant earliestSlaughter(LocalDate withdrawalUntilDate) {
        return withdrawalUntilDate.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant();
    }

    /**
     * 合并多个含药配方/饲喂事件：取最晚末次饲喂时刻与各药物最大休药天数。
     *
     * @param contributions 每项为 {lastFeedAtUtc: Instant, maxWithdrawalDays: int}
     * @return 合并后的最晚饲喂时刻、决定性最大休药天数及对应届满日；无贡献项返回 null
     */
    public static MergedWithdrawal merge(Map.Entry<Instant, Integer>... contributions) {
        Instant latestFeed = null;
        int maxDays = 0;
        for (Map.Entry<Instant, Integer> e : contributions) {
            if (e.getKey() == null) {
                continue;
            }
            if (latestFeed == null || e.getKey().isAfter(latestFeed)) {
                latestFeed = e.getKey();
            }
            maxDays = Math.max(maxDays, e.getValue());
        }
        if (latestFeed == null) {
            return null;
        }
        LocalDate until = withdrawalUntilDate(latestFeed, maxDays);
        return new MergedWithdrawal(latestFeed, maxDays, until, earliestSlaughter(until));
    }

    /**
     * 合并结果。
     *
     * @param latestFeedAtUtc       最晚末次含药饲喂时刻
     * @param maxWithdrawalDays     各药物最大休药天数
     * @param withdrawalUntilDate   休药期届满日（UTC 日历日）
     * @param earliestSlaughterUtc  最早合法出栏时刻（UTC）
     */
    public record MergedWithdrawal(
            Instant latestFeedAtUtc,
            int maxWithdrawalDays,
            LocalDate withdrawalUntilDate,
            Instant earliestSlaughterUtc
    ) {
    }
}

